40	func (db *db) getLocalCluster() *appv1.Cluster {
41		initLocalCluster.Do(func() {
42			info, err := db.kubeclientset.Discovery().ServerVersion()
43			if err == nil {
44				ver, verErr := version.ParseGeneric(info.GitVersion)
45				if verErr == nil {
46					//nolint:staticcheck
47					localCluster.ServerVersion = ver.String()
48				} else {
49					log.Warnf("Failed to parse Kubernetes server version: %v", verErr)
50				}
51				//nolint:staticcheck
52				localCluster.ConnectionState = appv1.ConnectionState{Status: appv1.ConnectionStatusSuccessful}
53			} else {
54				//nolint:staticcheck
55				localCluster.ConnectionState = appv1.ConnectionState{
56					Status:  appv1.ConnectionStatusFailed,
57					Message: err.Error(),
58				}
59			}
60		})
61		cluster := localCluster.DeepCopy()
62		now := metav1.Now()
63		//nolint:staticcheck
64		cluster.ConnectionState.ModifiedAt = &now
65		return cluster
66	}
